MemoryBarrier是更加严格的ExecutionBarrier，它在进行执行顺序的控制之余还保证了缓存的刷新。例如AB是两个命令，|是MemoryBarrier，那么A | B的命令能保证在A执行完并将所有的cache都刷入之后(保证缓存的一致性)，再执行B。
在Pipeline Barrier API中，可以指定三个数组。这三个数组，分别定义了不同类型的memory barrier: 全局memory barrier
buffer上的memory barrier
<br>image上的memory barrier 全局memory barrier只有src的访问mask和dst的访问mask，因此作用于当前所有的resource。需要具体操纵某个resource的时候，根据resource的类型，分别使用buffer或者image的memory barrier.[<a data-tooltip-position="top" aria-label="https://zhuanlan.zhihu.com/p/80692115" rel="noopener nofollow" class="external-link is-unresolved" href="https://zhuanlan.zhihu.com/p/80692115" target="_self">引用</a>]
// 奇怪的是 居然没有设置srcAccessMask
VkImageMemoryBarrier copy_barrier[1] = {};
copy_barrier[0].sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
copy_barrier[0].dstAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
copy_barrier[0].oldLayout = VK_IMAGE_LAYOUT_UNDEFINED;
copy_barrier[0].newLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
// 当队列族不变时都设置为VK_QUEUE_FAMILY_IGNORED
copy_barrier[0].srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
copy_barrier[0].dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
copy_barrier[0].image = bd-&gt;FontImage;
copy_barrier[0].subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
copy_barrier[0].subresourceRange.levelCount = 1;
copy_barrier[0].subresourceRange.layerCount = 1;
// 需要注意，置barrier是通过cmd进行的，说明这也是在command buffer里的一个命令
// 这里的srcStage是Host，dstStage是Transition，是从host拷贝到Image的过程大概
vkCmdPipelineBarrier(command_buffer, VK_PIPELINE_STAGE_HOST_BIT, VK_PIPELINE_STAGE_TRANSFER_BIT, 0, 0, nullptr, 0, nullptr, 1, copy_barrier); // 看起来在GPU里 Buffer里的数据需要拷贝到Image里面
VkBufferImageCopy region = {};
region.imageSubresource.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
region.imageSubresource.layerCount = 1;
region.imageExtent.width = width;
region.imageExtent.height = height;
region.imageExtent.depth = 1;
vkCmdCopyBufferToImage(command_buffer, bd-&gt;UploadBuffer, bd-&gt;FontImage, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &amp;region); // 在拷贝之后设置barrier，在执行完拷贝指令并将缓存刷到最新之后，再进行下一个Stage
VkImageMemoryBarrier use_barrier[1] = {};
use_barrier[0].sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
use_barrier[0].srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
use_barrier[0].dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
use_barrier[0].oldLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
use_barrier[0].newLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
use_barrier[0].srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
use_barrier[0].dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
use_barrier[0].image = bd-&gt;FontImage;
use_barrier[0].subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
use_barrier[0].subresourceRange.levelCount = 1;
use_barrier[0].subresourceRange.layerCount = 1;
vkCmdPipelineBarrier(command_buffer, VK_PIPELINE_STAGE_TRANSFER_BIT, VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT, 0, 0, nullptr, 0, nullptr, 1, use_barrier);
