上面的CreateOrResizeBuffer又是ImGUI封装的函数，其函数定义如下：它们分别创建了Vertex和Index Buffer。 static void CreateOrResizeBuffer(VkBuffer&amp; buffer, VkDeviceMemory&amp; buffer_memory, VkDeviceSize&amp; p_buffer_size, size_t new_size, VkBufferUsageFlagBits usage) { ImGui_ImplVulkan_Data* bd = ImGui_ImplVulkan_GetBackendData(); ImGui_ImplVulkan_InitInfo* v = &amp;bd-&gt;VulkanInitInfo; VkResult err; if (buffer != VK_NULL_HANDLE) vkDestroyBuffer(v-&gt;Device, buffer, v-&gt;Allocator); if (buffer_memory != VK_NULL_HANDLE) vkFreeMemory(v-&gt;Device, buffer_memory, v-&gt;Allocator); // ceil，奇怪的是，明明在创建字体Atlas的贴图时并没有考虑对齐的问题 // 试了一下，其实不对齐也没有问题 VkDeviceSize vertex_buffer_size_aligned = ((new_size - 1) / bd-&gt;BufferMemoryAlignment + 1) * bd-&gt;BufferMemoryAlignment; VkBufferCreateInfo buffer_info = {}; buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO; buffer_info.size = vertex_buffer_size_aligned; // usage用来表明是Vertex还是Index之类 buffer_info.usage = usage; buffer_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE; // 创建Buffer err = vkCreateBuffer(v-&gt;Device, &amp;buffer_info, v-&gt;Allocator, &amp;buffer); check_vk_result(err); VkMemoryRequirements req; vkGetBufferMemoryRequirements(v-&gt;Device, buffer, &amp;req); bd-&gt;BufferMemoryAlignment = (bd-&gt;BufferMemoryAlignment &gt; req.alignment) ? bd-&gt;BufferMemoryAlignment : req.alignment; VkMemoryAllocateInfo alloc_info = {}; alloc_info.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO; alloc_info.allocationSize = req.size; alloc_info.memoryTypeIndex = ImGui_ImplVulkan_MemoryType(VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT, req.memoryTypeBits); // 为Buffer分配内存 err = vkAllocateMemory(v-&gt;Device, &amp;alloc_info, v-&gt;Allocator, &amp;buffer_memory); check_vk_result(err); // 将Buffer和内存绑定 err = vkBindBufferMemory(v-&gt;Device, buffer, buffer_memory, 0); check_vk_result(err); p_buffer_size = req.size; }
