先看看ImGui中的Vulkan窗口结构体：struct ImGui_ImplVulkanH_Window
{ int Width; int Height; VkSwapchainKHR Swapchain; VkSurfaceKHR Surface; VkSurfaceFormatKHR SurfaceFormat; VkPresentModeKHR PresentMode; VkRenderPass RenderPass; VkPipeline Pipeline; // The window pipeline may uses a different VkRenderPass than the one passed in ImGui_ImplVulkan_InitInfo bool ClearEnable; VkClearValue ClearValue; uint32_t FrameIndex; // Current frame being rendered to (0 &lt;= FrameIndex &lt; FrameInFlightCount) uint32_t ImageCount; // Number of simultaneous in-flight frames (returned by vkGetSwapchainImagesKHR, usually derived from min_image_count) uint32_t SemaphoreIndex; // Current set of swapchain wait semaphores we're using (needs to be distinct from per frame data) ImGui_ImplVulkanH_Frame* Frames; ImGui_ImplVulkanH_FrameSemaphores* FrameSemaphores; ImGui_ImplVulkanH_Window() { memset((void*)this, 0, sizeof(*this)); PresentMode = (VkPresentModeKHR)~0; // Ensure we get an error if user doesn't set this. ClearEnable = true; }
};
后文所做的事情无非就是把这个结构体填充完毕。static VkAllocationCallbacks* g_Allocator = NULL;
static VkInstance g_Instance = VK_NULL_HANDLE;
static VkPhysicalDevice g_PhysicalDevice = VK_NULL_HANDLE;
static VkDevice g_Device = VK_NULL_HANDLE;
static uint32_t g_QueueFamily = (uint32_t)-1;
static VkQueue g_Queue = VK_NULL_HANDLE;
static VkDebugReportCallbackEXT g_DebugReport = VK_NULL_HANDLE;
static VkPipelineCache g_PipelineCache = VK_NULL_HANDLE;
static VkDescriptorPool g_DescriptorPool = VK_NULL_HANDLE; static ImGui_ImplVulkanH_Window g_MainWindowData;// 这是imgui用来控制vulkan渲染到窗口的
static int g_MinImageCount = 2;
static bool g_SwapChainRebuild = false;
然后按顺序执行下列步骤。官方教程说Vulkan Instance维护了每个Vulkan应用的状态，因此必须先进行vulkan instance的创建。<a data-tooltip-position="top" aria-label="https://blog.csdn.net/Bleach3/article/details/105821759" rel="noopener nofollow" class="external-link is-unresolved" href="https://blog.csdn.net/Bleach3/article/details/105821759" target="_self">此文章</a>也说明了vulkan instance的初始化过程中会加载并初始化GPU驱动。VkInstanceCreateInfo create_info = {};
create_info.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;
create_info.enabledExtensionCount = extensions_count;
create_info.ppEnabledExtensionNames = extensions;
err = vkCreateInstance(&amp;create_info, g_Allocator, &amp;g_Instance);
在退出应用时需要自行销毁此instance。下列代码只是获取了GPU设备信息之后选择了一个GPU设备作为此引用的vulkan设备，并把设备信息储存起来，没有进行其他操作。uint32_t gpu_count;
err = vkEnumeratePhysicalDevices(g_Instance, &amp;gpu_count, NULL);
check_vk_result(err);
IM_ASSERT(gpu_count &gt; 0); VkPhysicalDevice* gpus = (VkPhysicalDevice*)malloc(sizeof(VkPhysicalDevice) * gpu_count);
err = vkEnumeratePhysicalDevices(g_Instance, &amp;gpu_count, gpus);
check_vk_result(err); // If a number &gt;1 of GPUs got reported, find discrete GPU if present, or use first one available. This covers
// most common cases (multi-gpu/integrated+dedicated graphics). Handling more complicated setups (multiple
// dedicated GPUs) is out of scope of this sample.
// 这里优先选择独显，如无独显则选择获取的第一个GPU设备
int use_gpu = 0;
for (int i = 0; i &lt; (int)gpu_count; i++)
{ VkPhysicalDeviceProperties properties; vkGetPhysicalDeviceProperties(gpus[i], &amp;properties); if (properties.deviceType == VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU) { use_gpu = i; break; }
} g_PhysicalDevice = gpus[use_gpu];
free(gpus);
<br>
[Vulkan 的几乎所有操作，从绘制到加载纹理都需要将操作 指令提交给一个队列，然后才能执行。Vulkan 有多种不同类型的队列，它们属于不同的队列族，每个队列族的队列只允许执行特定的一部分指令。 比如，可能存在只允许执行计算相关指令的队列族和只允许执行内存传输的队列族。](<a data-tooltip-position="top" aria-label="https://zhuanlan.zhihu.com/p/460921731" rel="noopener nofollow" class="external-link is-unresolved" href="https://zhuanlan.zhihu.com/p/460921731" target="_self">Vulkan从入门到精通31-队列族和逻辑设备 - 知乎 (zhihu.com)</a>) uint32_t count;
vkGetPhysicalDeviceQueueFamilyProperties(g_PhysicalDevice, &amp;count, NULL);
VkQueueFamilyProperties* queues = (VkQueueFamilyProperties*)malloc(sizeof(VkQueueFamilyProperties) * count);
vkGetPhysicalDeviceQueueFamilyProperties(g_PhysicalDevice, &amp;count, queues);
for (uint32_t i = 0; i &lt; count; i++) if (queues[i].queueFlags &amp; VK_QUEUE_GRAPHICS_BIT) { g_QueueFamily = i; break; }
free(queues);
IM_ASSERT(g_QueueFamily != (uint32_t)-1); 创建逻辑设备时需要传入queue的参数，因此需要先创建queue info才能创建设备。在创建设备时也会创建queue。
逻辑设备肯定就区别于物理设备，之后需要vulkan进行交互的都是逻辑设备。int device_extension_count = 1;
const char* device_extensions[] = { "VK_KHR_swapchain" };
const float queue_priority[] = { 1.0f };
VkDeviceQueueCreateInfo queue_info[1] = {};
queue_info[0].sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
queue_info[0].queueFamilyIndex = g_QueueFamily;
queue_info[0].queueCount = 1;
queue_info[0].pQueuePriorities = queue_priority;
VkDeviceCreateInfo create_info = {};
create_info.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;
create_info.queueCreateInfoCount = sizeof(queue_info) / sizeof(queue_info[0]);
create_info.pQueueCreateInfos = queue_info;
create_info.enabledExtensionCount = device_extension_count;
create_info.ppEnabledExtensionNames = device_extensions;
err = vkCreateDevice(g_PhysicalDevice, &amp;create_info, g_Allocator, &amp;g_Device);
check_vk_result(err);
vkGetDeviceQueue(g_Device, g_QueueFamily, 0, &amp;g_Queue);
同样地，在程序退出时需要调用kDestroyDevice。<br>在vulkan中，descriptor大概是着色器使用的变量，最终组成discriptor set之后才能被shader使用。<a data-tooltip-position="top" aria-label="https://zhuanlan.zhihu.com/p/450434645" rel="noopener nofollow" class="external-link is-unresolved" href="https://zhuanlan.zhihu.com/p/450434645" target="_self">这篇文章</a>对descriptor解释得蛮清楚。<br><img alt="v2-61ccfca7561dc80ff9e2cebfeaa446e3_1440w" src=".html" referrerpolicy="no-referrer" target="_self">VkDescriptorPoolSize pool_sizes[] =
{ { VK_DESCRIPTOR_TYPE_SAMPLER, 1000 }, { VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 1000 }, { VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE, 1000 }, { VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 1000 }, { VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER, 1000 }, { VK_DESCRIPTOR_TYPE_STORAGE_TEXEL_BUFFER, 1000 }, { VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 1000 }, { VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1000 }, { VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC, 1000 }, { VK_DESCRIPTOR_TYPE_STORAGE_BUFFER_DYNAMIC, 1000 }, { VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT, 1000 }
};
VkDescriptorPoolCreateInfo pool_info = {};
pool_info.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
pool_info.flags = VK_DESCRIPTOR_POOL_CREATE_FREE_DESCRIPTOR_SET_BIT;
pool_info.maxSets = 1000 * IM_ARRAYSIZE(pool_sizes);
pool_info.poolSizeCount = (uint32_t)IM_ARRAYSIZE(pool_sizes);
pool_info.pPoolSizes = pool_sizes;
err = vkCreateDescriptorPool(g_Device, &amp;pool_info, g_Allocator, &amp;g_DescriptorPool);
check_vk_result(err);
首先要使用某些方法创建窗口。以GLFW为例，可以先用其创建一个窗口。if (!glfwInit()) return 1; glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
GLFWwindow* window = glfwCreateWindow(1920, 1080, "Doxel", NULL, NULL);
接下来就是vulkan时间。vulkan中有WSI(Window Surface Intergration)的概念，也就是将vulkan渲染的结果显示在某个window上。surface的创建方法如下：VkSurfaceKHR surface;
glfwCreateWindowSurface(g_Instance, window, g_Allocator, &amp;surface);
而后创建色彩空间和格式信息。下面的imgui函数封装了访问和匹配vulkan设备支持的格式信息，返回的是VkSurfaceFormatKHR类型值，此类型由色彩空间和格式组成。const VkFormat requestSurfaceImageFormat[] = { VK_FORMAT_B8G8R8A8_UNORM, VK_FORMAT_R8G8B8A8_UNORM, VK_FORMAT_B8G8R8_UNORM, VK_FORMAT_R8G8B8_UNORM };
const VkColorSpaceKHR requestSurfaceColorSpace = VK_COLORSPACE_SRGB_NONLINEAR_KHR;
wd-&gt;SurfaceFormat = ImGui_ImplVulkanH_SelectSurfaceFormat(g_PhysicalDevice, wd-&gt;Surface, requestSurfaceImageFormat, (size_t)IM_ARRAYSIZE(requestSurfaceImageFormat), requestSurfaceColorSpace); 呈现模式主要控制了，在渲染出一个图像后，采用什么策略显示到屏幕。各个策略如下，fifo策略在帧数拉满时没有画面撕裂。 VK_PRESENT_MODE_IMMEDIATE_KHR：你的程序提交的图像会立即传输到屏幕，这可能会导致撕裂； VK_PRESENT_MODE_FIFO_KHR：交换链是个队列，显示的时候从队列头拿一个图像，程序插入渲染的图像到队列尾。如果队列满了程序就要等待，这差不多像是垂直同步，显示刷新的时刻就是垂直空白； VK_PRESENT_MODE_FIFO_RELAXED_KHR：在最后一个垂直空白的时候，如果应用迟到，且队列为空，该模式才会和前面的那个有所不同。这样就不等到下一个垂直空白，图像会直接传输到屏幕，可能导致撕裂； VK_PRESENT_MODE_MAILBOX_KHR：这是第二个模式的又一个变种，当队列满的时候，它不会阻塞应用，已经在队列中的图像会被新的替换。这个模式可以实现三重缓冲，避免撕裂，比使用双重缓冲的垂直同步减少很多延迟。 很显然，下列代码中的imgui函数也是封装了访问和匹配vulkan设备显示方法。#ifdef IMGUI_UNLIMITED_FRAME_RATE VkPresentModeKHR present_modes[] = { VK_PRESENT_MODE_MAILBOX_KHR, VK_PRESENT_MODE_IMMEDIATE_KHR, VK_PRESENT_MODE_FIFO_KHR };
#else VkPresentModeKHR present_modes[] = { VK_PRESENT_MODE_FIFO_KHR };
#endif wd-&gt;PresentMode = ImGui_ImplVulkanH_SelectPresentMode(g_PhysicalDevice, wd-&gt;Surface, &amp;present_modes[0], IM_ARRAYSIZE(present_modes));
首先初始化CreateInfo结构体。而后进行SwapChain的创建以及对应Image缓冲的创建。VkSwapchainCreateInfoKHR info = {};
info.sType = VK_STRUCTURE_TYPE_SWAPCHAIN_CREATE_INFO_KHR;
info.surface = wd-&gt;Surface;
info.minImageCount = min_image_count;
info.imageFormat = wd-&gt;SurfaceFormat.format;
info.imageColorSpace = wd-&gt;SurfaceFormat.colorSpace;
info.imageArrayLayers = 1;
info.imageUsage = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
info.imageSharingMode = VK_SHARING_MODE_EXCLUSIVE; // Assume that graphics family == present family
info.preTransform = VK_SURFACE_TRANSFORM_IDENTITY_BIT_KHR;
info.compositeAlpha = VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR;
info.presentMode = wd-&gt;PresentMode;
info.clipped = VK_TRUE;
info.oldSwapchain = old_swapchain;
VkSurfaceCapabilitiesKHR cap; // 这个capability包含了swapchain的最小缓存数和最大缓冲数之类
err = vkGetPhysicalDeviceSurfaceCapabilitiesKHR(physical_device, wd-&gt;Surface, &amp;cap); err = vkCreateSwapchainKHR(device, &amp;info, allocator, &amp;wd-&gt;Swapchain);
err = vkGetSwapchainImagesKHR(device, wd-&gt;Swapchain, &amp;wd-&gt;ImageCount, nullptr);
在imgui里封装了FrameBuffer及其对应的Image和ImageView及需要属性，称作Frame，用来控制buffer和同步的。struct ImGui_ImplVulkanH_Frame
{ VkCommandPool CommandPool; VkCommandBuffer CommandBuffer; VkFence Fence; VkImage Backbuffer; VkImageView BackbufferView; VkFramebuffer Framebuffer;
}; struct ImGui_ImplVulkanH_FrameSemaphores
{ VkSemaphore ImageAcquiredSemaphore; VkSemaphore RenderCompleteSemaphore;
};
<br>vulkan中的Render Pass和Unity中Shader的Render Pass感觉上来说不同，拿延迟渲染举例，延迟渲染有渲染GBuffer的阶段和屏幕空间计算光照的部分(我也不知道为什么这么分成两个阶段)，整个延迟渲染是一个Render Pass，但分为了GBuffer和屏幕空间两个pipeline，所以Render Pass应该是最高层的渲染流程。[<a data-tooltip-position="top" aria-label="https://zhuanlan.zhihu.com/p/418277173" rel="noopener nofollow" class="external-link is-unresolved" href="https://zhuanlan.zhihu.com/p/418277173" target="_self">引用</a>]// attachment
VkAttachmentDescription attachment = {};
attachment.format = wd-&gt;SurfaceFormat.format;
attachment.samples = VK_SAMPLE_COUNT_1_BIT;
attachment.loadOp = wd-&gt;ClearEnable ? VK_ATTACHMENT_LOAD_OP_CLEAR : VK_ATTACHMENT_LOAD_OP_DONT_CARE;
attachment.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
attachment.stencilLoadOp = VK_ATTACHMENT_LOAD_OP_DONT_CARE;
attachment.stencilStoreOp = VK_ATTACHMENT_STORE_OP_DONT_CARE;
attachment.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
attachment.finalLayout = VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;
// attachment reference
VkAttachmentReference color_attachment = {};
color_attachment.attachment = 0;
color_attachment.layout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
// 一个Render Pass由若干Subpass组成
VkSubpassDescription subpass = {};
// bind point有compute和graphics两种，compute是计算管线，graphics是图形渲染管线
subpass.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
subpass.colorAttachmentCount = 1;
subpass.pColorAttachments = &amp;color_attachment;
// subpass依赖
VkSubpassDependency dependency = {};
// VK_SUBPASS_EXTERNAL表示了该subpass之前的subpass
dependency.srcSubpass = VK_SUBPASS_EXTERNAL;
// 0表示当前subpass吧大概
dependency.dstSubpass = 0;
dependency.srcStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
dependency.dstStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
dependency.srcAccessMask = 0;
dependency.dstAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
// Render Pass Create Info
VkRenderPassCreateInfo info = {};
info.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO;
info.attachmentCount = 1;
info.pAttachments = &amp;attachment;
info.subpassCount = 1;
info.pSubpasses = &amp;subpass;
info.dependencyCount = 1;
info.pDependencies = &amp;dependency;
err = vkCreateRenderPass(device, &amp;info, allocator, &amp;wd-&gt;RenderPass);
check_vk_result(err); 管线着色器不能直接访问图形对象。作为替代，image view相当于一个代理，代表了image所占据的连续内存区域，并且包含一些额外的成员用来对image进行读写。
An image view is quite literally a view into an image. It describes how to access the image and which part of the image to access, for example if it should be treated as a 2D texture depth texture without any mipmapping levels.
也就是说，ImageView帮你实现了访问Image像素之类的方法。下文为每个Image都给创建一个ImageView。VkImageViewCreateInfo info = {};
info.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
info.viewType = VK_IMAGE_VIEW_TYPE_2D;
info.format = wd-&gt;SurfaceFormat.format;
info.components.r = VK_COMPONENT_SWIZZLE_R;
info.components.g = VK_COMPONENT_SWIZZLE_G;
info.components.b = VK_COMPONENT_SWIZZLE_B;
info.components.a = VK_COMPONENT_SWIZZLE_A;
VkImageSubresourceRange image_range = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1 };
info.subresourceRange = image_range;
for (uint32_t i = 0; i &lt; wd-&gt;ImageCount; i++)
{ ImGui_ImplVulkanH_Frame* fd = &amp;wd-&gt;Frames[i]; info.image = fd-&gt;Backbuffer; err = vkCreateImageView(device, &amp;info, allocator, &amp;fd-&gt;BackbufferView); check_vk_result(err);
}
<br>
Frame buffer（帧缓冲区）封装了 color buffer image和depth buffer image。其中color buffer image为从swap chain获取的image，frame buffer的创建个数需要跟swap chain的image的数量对应，比如，双缓冲的swap chain需要对应建立2个frame buffer。
Frame buffer还负责把render pass的attachment跟ImageView关联起来。[<a data-tooltip-position="top" aria-label="https://zhuanlan.zhihu.com/p/48066609" rel="noopener nofollow" class="external-link is-unresolved" href="https://zhuanlan.zhihu.com/p/48066609" target="_self">引用</a>]<img style="zoom:67%;" alt="v2-e3953472599247115e1d7635f8561786_720w" src=".html" referrerpolicy="no-referrer" target="_self">
VkImageView attachment[1];
VkFramebufferCreateInfo info = {};
info.sType = VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO;
info.renderPass = wd-&gt;RenderPass;
info.attachmentCount = 1;
info.pAttachments = attachment;
info.width = wd-&gt;Width;
info.height = wd-&gt;Height;
info.layers = 1;
// 每个ImageView需要一个FrameBuffer
for (uint32_t i = 0; i &lt; wd-&gt;ImageCount; i++)
{ ImGui_ImplVulkanH_Frame* fd = &amp;wd-&gt;Frames[i]; attachment[0] = fd-&gt;BackbufferView; err = vkCreateFramebuffer(device, &amp;info, allocator, &amp;fd-&gt;Framebuffer); check_vk_result(err);
}
Command Buffer是储存GPU绘制命令的Buffer。同时还创建每个Command Buffer的信号量，用来完成每个渲染批次之间的同步。和所有的Pool一样，Command Buffer的内存需要用Pool来分配。<br>
可以看到Fence和Semaphore都会在vkQueueSubmit时作为参数传入，不同之处是，Fence用于阻塞CPU直到Queue中的命令执行结束（GPU、CPU之间的同步），而Semaphore用于不同的命令提交之间的同步（GPU、GPU之间的同步）。[<a data-tooltip-position="top" aria-label="https://zhuanlan.zhihu.com/p/380719229" rel="noopener nofollow" class="external-link is-unresolved" href="https://zhuanlan.zhihu.com/p/380719229" target="_self">引用</a>]
VkResult err;
// 每个Image都要一个Command Buffer，不知道为啥
for (uint32_t i = 0; i &lt; wd-&gt;ImageCount; i++)
{ ImGui_ImplVulkanH_Frame* fd = &amp;wd-&gt;Frames[i]; ImGui_ImplVulkanH_FrameSemaphores* fsd = &amp;wd-&gt;FrameSemaphores[i]; { // 创建Command Pool VkCommandPoolCreateInfo info = {}; info.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO; // Command Buffer对象之间相互独立，不会被一起重置 info.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT; info.queueFamilyIndex = queue_family; err = vkCreateCommandPool(device, &amp;info, allocator, &amp;fd-&gt;CommandPool); check_vk_result(err); } { // 创建Command Buffer VkCommandBufferAllocateInfo info = {}; info.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO; info.commandPool = fd-&gt;CommandPool; // Primary Command Buffer不能被其他Command Buffer调用 info.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY; info.commandBufferCount = 1; err = vkAllocateCommandBuffers(device, &amp;info, &amp;fd-&gt;CommandBuffer); check_vk_result(err); } { // 创建fence VkFenceCreateInfo info = {}; info.sType = VK_STRUCTURE_TYPE_FENCE_CREATE_INFO; info.flags = VK_FENCE_CREATE_SIGNALED_BIT; err = vkCreateFence(device, &amp;info, allocator, &amp;fd-&gt;Fence); check_vk_result(err); } { // 创建获取和完成的信号量(?为啥是两个) VkSemaphoreCreateInfo info = {}; info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO; err = vkCreateSemaphore(device, &amp;info, allocator, &amp;fsd-&gt;ImageAcquiredSemaphore); check_vk_result(err); err = vkCreateSemaphore(device, &amp;info, allocator, &amp;fsd-&gt;RenderCompleteSemaphore); check_vk_result(err); }
}
一个Sampler包含了LOD(mip)，Filter(插值)，adressMode(平铺方式(即uv范围之外如何进行采样))VkSamplerCreateInfo info = {};
info.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
info.magFilter = VK_FILTER_LINEAR;
info.minFilter = VK_FILTER_LINEAR;
info.mipmapMode = VK_SAMPLER_MIPMAP_MODE_LINEAR;
info.addressModeU = VK_SAMPLER_ADDRESS_MODE_REPEAT;
info.addressModeV = VK_SAMPLER_ADDRESS_MODE_REPEAT;
info.addressModeW = VK_SAMPLER_ADDRESS_MODE_REPEAT;
info.minLod = -1000;
info.maxLod = 1000;
info.maxAnisotropy = 1.0f;
err = vkCreateSampler(v-&gt;Device, &amp;info, v-&gt;Allocator, &amp;bd-&gt;FontSampler);
前文说到，一个descriptor大概算是Shader里的一个变量，大概需要将descriptor绑定到真实的GPU变量上。在以此创建LayoutBingding之后再创建Layout。VkSampler sampler[1] = {bd-&gt;FontSampler};
VkDescriptorSetLayoutBinding binding[1] = {};
binding[0].descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
binding[0].descriptorCount = 1;
binding[0].stageFlags = VK_SHADER_STAGE_FRAGMENT_BIT;
binding[0].pImmutableSamplers = sampler; VkDescriptorSetLayoutCreateInfo info = {};
info.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
info.bindingCount = 1;
info.pBindings = binding;
err = vkCreateDescriptorSetLayout(v-&gt;Device, &amp;info, v-&gt;Allocator, &amp;bd-&gt;DescriptorSetLayout);
check_vk_result(err);
如果要创建例如MVP之类的变量，LayoutBinding可以使用下列代码：VkDescriptorSetLayoutBinding layout_binding = {};
// bingding表示是DescriptorSet中的第几个
layout_binding.binding = 0;
layout_binding.descriptorType = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
// count表示该DescriptorSet里有多少个Descriptor
layout_binding.descriptorCount = 1;
layout_binding.stageFlags = VK_SHADER_STAGE_VERTEX_BIT;
layout_binding.pImmutableSamplers = NULL; VkDescriptorSetLayoutCreateInfo descriptor_layout = {};
descriptor_layout.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
descriptor_layout.pNext = NULL;
descriptor_layout.bindingCount = 1;
descriptor_layout.pBindings = layout_bindings; info.desc_layout.resize(NUM_DESCRIPTOR_SETS);
res = vkCreateDescriptorSetLayout(info.device, &amp;descriptor_layout, NULL, info.desc_layout.data());
assert(res == VK_SUCCESS);
